  const create=async fields=>evaluate(`window.cssRequest('/api/admin/exam-configurations/save',{method:'POST',body:new URLSearchParams(${JSON.stringify(fields)})})`);
  const {id}=await create(spec),other=await create({...spec,title:'Kỳ thi độc lập'});
