  await waitFor(()=>evaluate("document.querySelectorAll('[data-code-participant]').length===2"));
  assert.deepEqual(await evaluate("[...document.querySelectorAll('[data-code-participant]:checked')].map(n=>n.value)"),['QA001']);
  await evaluate(`(()=>{const p=document.querySelector('#code-participants-form textarea');p.value=${JSON.stringify('ROSTER01,ROSTER01\nROSTER02')};p.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('#code-participants-form').requestSubmit();})()`);
  await waitFor(()=>evaluate("document.querySelector('[data-code-participant-result]').textContent.includes('Tạo mới 2 tài khoản')"));
  assert.equal(await evaluate("document.querySelector('[data-problem-statement]')===qaProblemNode && qaProblemNode.value==='Đề đang chỉnh chưa lưu'"),true);
  const saved=await evaluate(`fetch('/api/admin/workspace').then(r=>r.json()).then(d=>({own:d.exams.find(e=>e.id==='${id}').participants,other:d.exams.find(e=>e.id==='${other.id}').participants}))`);
  assert.deepEqual(saved.own,['QA001','ROSTER01','ROSTER02']);assert.deepEqual(saved.other,['QA001','QAEMPTY']);
  const login=await fetch(base+'/login',{method:'POST',redirect:'manual',headers:{Origin:base,'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({username:'ROSTER01',password:'ROSTER01'})});
  assert.equal(login.status,303);
  await submit('#exam-config-form',{});
  await waitFor(()=>evaluate("document.querySelectorAll('[data-code-participant]:checked').length===3"));
  assert.equal(await evaluate("document.querySelector('[data-problem-statement]').value"),'Đề đang chỉnh chưa lưu');
  await evaluate("document.querySelector('[data-code-participant][value=ROSTER02]').click()");
  await submit('#exam-config-form',{});
  await waitFor(()=>evaluate("document.querySelectorAll('[data-code-participant]:checked').length===2"));
  await evaluate("(()=>{const p=document.querySelector('#code-participants-form textarea');p.value='bad-id';p.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('#code-participants-form').requestSubmit();})()");
  await waitFor(()=>evaluate("document.querySelector('[data-code-participant-result]').getAttribute('role')==='alert'"));
  assert.equal(await evaluate("document.querySelector('#code-participants-form textarea').value"),'bad-id');
  await evaluate("(()=>{const p=document.querySelector('#code-participants-form textarea');p.value='';p.dispatchEvent(new Event('input',{bubbles:true}));})()");
  await noOverflow();await panelScreenshot('[data-code-participants]','code-exam-participants-desktop.png');
  await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
  await waitFor(()=>evaluate("document.querySelector('.main-sidebar').getBoundingClientRect().right<=1"));
  await noOverflow();await panelScreenshot('[data-code-participants]','code-exam-participants-mobile.png');
  await send('Emulation.setDeviceMetricsOverride',{width:1440,height:1100,deviceScaleFactor:1,mobile:false});
  const moving=await create({...spec,title:'Đổi khóa học có danh sách đang chỉnh'});
  await navigate(base+`/admin?section=exam&exam=${moving.id}`);
  await evaluate(`document.querySelector('[data-code-participant][value=QAEMPTY]').click();document.querySelector('#exam-config-form [name=course_id]').value=${JSON.stringify(fixture.course)};document.querySelector('[data-code-control=start]').click()`);
  await waitFor(()=>evaluate("document.querySelector('#toast').textContent.includes('cập nhật danh sách của khóa học mới')"));
  assert.equal(await evaluate(`fetch('/api/admin/workspace').then(r=>r.json()).then(d=>d.exams.find(e=>e.id==='${moving.id}').course_id)`),null);
  await evaluate("document.querySelector('#code-participants-form').requestSubmit()");
